export function evaluate({inputs,time}){const u=inputs.launchSpeed,g=inputs.gravity,m=inputs.mass;const T=2*u/g;const t=Math.min(Math.max(time,0),T);const v=u-g*t,y=u*t-g*t*t/2,F=m*g,ta=u/g;const H=u*u/(2*g);
let st='Rising';if(time<=0)st='Ready to toss';else if(Math.abs(t-ta)<0.005)st='At the top';else if(t>=T-1e-9)st='Back at launch height';else if(t>ta)st='Falling';
const o=[];o.push(...sdk.panel({id:'lane.motion',x:10,y:34,w:305,h:370,title:'The motion',state:st}));
o.push(sdk.axis('axis.h',{x:60,y:380,length:320,orientation:'y',min:0,max:2.2,ticks:[0,1,2],label:'Height',unit:'m'}));
const py=380-y/2.2*320;o.push(sdk.circle('ball.toss',130,py,24,{}));
o.push(...sdk.vector('vec.v',{x:130,y:py},{value:v,direction:'up'},{scale:14,label:'v',role:'input'}));
o.push(...sdk.vector('vec.a',{x:160,y:py},{value:-g,direction:'up'},{scale:6,label:'a',role:'warning'}));
o.push(...sdk.callout(200,py<120?120:py,['v = '+sdk.format(v,2)+' m/s','a = '+sdk.format(-g,1)+' m/s^2','Fg = '+sdk.format(F,1)+' N'],{id:'callout.toss'}));
const pts=[];for(let i=0;i<=12;i++){const x=T*i/12*1.0;pts.push({x:Math.min(1.8,x),y:u-g*Math.min(1.8,x)});}
const cur=[];const n=Math.max(1,Math.round(t/T*12));for(let i=0;i<=n;i++){const x=t*i/n;cur.push({x,y:u-g*x});}
const full=[];for(let i=0;i<=12;i++){const x=1.8*i/12;full.push({x,y:Math.max(-5.5,Math.min(5.5,u-g*x))});}
o.push(sdk.plot('plot.vt',{x:340,y:44,w:290,h:330,axes:{x:{label:'t',min:0,max:1.8,unit:'s'},y:{label:'v',min:-5.5,max:5.5,unit:'m/s'}},series:[{label:'v = u - g t',kind:'line',points:full},{label:'so far',kind:'line',points:cur}]}));
o.push(sdk.text('plot.vt.note',480,402,'slope a = -g = '+sdk.format(-g,1)+' m/s^2',{align:'middle',role:'warning'}));
return {frame:{width:640,height:420,objects:o,readouts:[{id:'velocity',value:v},{id:'acceleration',value:-g},{id:'force',value:F},{id:'motionState',value:st}]},quantities:{launchSpeed:u,gravity:g,mass:m,apexTime:ta,apexHeight:H,height:y,velocity:v,acceleration:-g,force:F}};}
